import BudgetForm from './components/BudgetForm.jsx';
import PlanResult from './components/PlanResult.jsx';

// PDD section: objective — client-only React demonstration
export default function App() {
  const [result, setResult] = useState(null);

  return (
    <div className="app">
      <h1>Seven Dinners Planner</h1>
      <BudgetForm onResult={setResult} />
      {result && <PlanResult result={result} />}
      <footer>
        {/* PDD section: pricing — mandatory disclaimer */}
        <p className="disclaimer">
          Demonstration prices only — not live grocery prices or nutritional advice.
        </p>
      </footer>
    </div>
  );
}
