      "content": "import React, { useState } from 'react';
import { validateInputs, buildPlan } from '../lib/planner.js';

// PDD section: io — integer inputs, default budgetCents=12000 familySize=4
export default function BudgetForm({ onResult }) {
  const [budgetDollars, setBudgetDollars] = useState('120.00');
  const [familySize, setFamilySize] = useState('4');
  const [validationError, setValidationError] = useState('');

  function handleSubmit(e) {
    e.preventDefault();
    setValidationError('');

    // Convert dollar string to integer cents
    const dollarVal = budgetDollars.trim();
    const parsedDollars = parseFloat(dollarVal);
    // Require the entered value to be a valid number and convert to integer cents
    let budgetCents;
    if (isNaN(parsedDollars) || dollarVal === '') {
      setValidationError('Budget must be a valid number (e.g. 120.00).');
      return;
    }
    budgetCents = Math.round(parsedDollars * 100);
    // Guard: after rounding must still be a safe integer
    if (!Number.isInteger(budgetCents)) {
      setValidationError('Budget could not be converted to integer cents.');
      return;
    }

    const parsedFamily = parseInt(familySize, 10);

    // PDD section: io — reject non-integer, missing or out-of-range inputs with a visible error
    const error = validateInputs(budgetCents, parsedFamily);
    if (error) {
      setValidationError(error);
      return;
    }

    const plan = buildPlan(budgetCents, parsedFamily);
    onResult(plan);
  }

  return (
    <form className="budget-form" onSubmit={handleSubmit}>
      <div className="field">
        <label htmlFor="budget">Budget ($)</label>
        <input
          id="budget"
          type="number"
          min="0"
          step="0.01"
          value={budgetDollars}
          onChange={(e) => setBudgetDollars(e.target.value)}
        />
        <span className="hint">Enter total budget in dollars (e.g. 120.00 = $120)</span>
      </div>
      <div className="field">
        <label htmlFor="familySize">Family size (1–12)</label>
        <input
          id="familySize"
          type="number"
          min="1"
          max="12"
          step="1"
          value={familySize}
          onChange={(e) => setFamilySize(e.target.value)}
        />
      </div>
      {validationError && (
        <p className="error" role="alert">{validationError}</p>
      )}
      <button type="submit">Calculate Plan</button>
    </form>
  );
}
