      "content": "import React from 'react';

// PDD section: success — display both feasible and insufficient_budget outcomes
function formatCents(cents) {
  return '$' + (cents / 100).toFixed(2);
}

export default function PlanResult({ result }) {
  const { status, days, shoppingList, totalCostCents, requiredBudgetCents } = result;

  return (
    <div className="plan-result">
      {/* PDD section: pricing — mandatory disclaimer also shown in result area */}
      <p className="disclaimer">
        Demonstration prices only — not live grocery prices or nutritional advice.
      </p>

      <h2>Result: <span className={status === 'feasible' ? 'feasible' : 'insufficient'}>{status}</span></h2>

      <p>Total cost: <strong>{formatCents(totalCostCents)}</strong></p>
      <p>Required budget: <strong>{formatCents(requiredBudgetCents)}</strong></p>

      {/* PDD section: success — insufficient_budget: visible explanation */}
      {status === 'insufficient_budget' && (
        <p className="error" role="alert">
          Your budget of {formatCents(result.budgetCents)} is insufficient.
          The required budget is {formatCents(requiredBudgetCents)}.
          Days and shopping list are not shown for an infeasible plan.
        </p>
      )}

      {/* PDD section: success — feasible: seven distinct days and shopping list */}
      {status === 'feasible' && (
        <>
          <h3>Weekly Meal Plan</h3>
          <ol>
            {days.map((day) => (
              <li key={day.day}>
                <strong>Day {day.day}:</strong> {day.mealName} —{' '}
                {formatCents(day.mealCostCents)}
              </li>
            ))}
          </ol>

          <h3>Shopping List</h3>
          <table className="shopping-table">
            <thead>
              <tr>
                <th>Ingredient</th>
                <th>Qty (portions)</th>
                <th>Unit price</th>
                <th>Line cost</th>
              </tr>
            </thead>
            <tbody>
              {shoppingList.map((item) => (
                <tr key={item.ingredient}>
                  <td>{item.ingredient}</td>
                  <td>{item.quantity}</td>
                  <td>{formatCents(item.unitPriceCents)}</td>
                  <td>{formatCents(item.lineCostCents)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </>
      )}
    </div>
  );
}
