      "content": "// PDD section: calculation — pure integer-cents calculation; no floats, no invented prices
import { MEAL_CATALOG, DEMO_PRICES_CENTS } from '../data/catalog.js';

/**
 * PDD section: io — validate inputs strictly; do not silently clamp.
 * Returns an error string or empty string if valid.
 */
export function validateInputs(budgetCents, familySize) {
  if (!Number.isInteger(budgetCents)) {
    return 'Budget must be a whole number of cents (integer).';
  }
  if (budgetCents < 0) {
    return 'Budget must be 0 or greater.';
  }
  if (!Number.isInteger(familySize)) {
    return 'Family size must be an integer.';
  }
  if (familySize < 1 || familySize > 12) {
    return 'Family size must be between 1 and 12.';
  }
  return '';
}

/**
 * PDD section: calculation
 * Arithmetic trace for familySize=4:
 *   rice-beans:        (rice 25 + beans 50) * 4 = 300
 *   tomato-pasta:      (pasta 40 + tomato 30) * 4 = 280
 *   lentil-stew:       (lentils 45 + tomato 30) * 4 = 300
 *   vegetable-rice:    (rice 25 + mixedVeg 60) * 4 = 340
 *   chickpea-couscous: (chickpeas 50 + couscous 40) * 4 = 360
 *   potatoes-peas:     (potatoes 35 + peas 35) * 4 = 280
 *   vegetable-oats:    (oats 30 + mixedVeg 60) * 4 = 360
 *   total = 300+280+300+340+360+280+360 = 2220  ✓ PDD example
 */
export function buildPlan(budgetCents, familySize) {
  // Accumulate shopping quantities by ingredient
  const quantities = {};

  const days = MEAL_CATALOG.map((meal, index) => {
    let mealCostCents = 0;
    for (const ingredient of meal.ingredients) {
      const unitPrice = DEMO_PRICES_CENTS[ingredient];
      const qty = familySize; // one portion per person per occurrence
      mealCostCents += unitPrice * qty; // integer arithmetic only
      quantities[ingredient] = (quantities[ingredient] || 0) + qty;
    }
    return {
      day: index + 1,
      mealId: meal.id,
      mealName: meal.name,
      mealCostCents,
    };
  });

  // PDD section: calculation — aggregate shopping list
  const shoppingList = Object.keys(quantities).map((ingredient) => {
    const quantity = quantities[ingredient];
    const unitPriceCents = DEMO_PRICES_CENTS[ingredient];
    return {
      ingredient,
      quantity,
      unitPriceCents,
      lineCostCents: unitPriceCents * quantity, // integer arithmetic only
    };
  });

  // PDD section: calculation — totalCostCents is sum of all seven meal costs
  const totalCostCents = days.reduce((sum, d) => sum + d.mealCostCents, 0);
  const requiredBudgetCents = totalCostCents;

  // PDD section: success — feasible or insufficient_budget; never claim feasible when not
  if (totalCostCents <= budgetCents) {
    return {
      status: 'feasible',
      days,
      shoppingList,
      totalCostCents,
      requiredBudgetCents,
      budgetCents,
    };
  } else {
    // PDD section: success — empty days and shoppingList on insufficient_budget
    return {
      status: 'insufficient_budget',
      days: [],
      shoppingList: [],
      totalCostCents,
      requiredBudgetCents,
      budgetCents,
    };
  }
}
